import { useState } from "react";
import type { Dispatch } from "react";

import type { ActionsApi } from "../actions";
import type { SupportBundle } from "../bridge/types";
import { useT } from "../i18n";
import type { Action, State } from "../state/store";

// Embedded at build time (`?raw`), not read from disk: the renderer has no
// filesystem capability (05-02 §7) and the notices must work offline. The file
// is generated by scripts/generate-licenses.mjs and gated by `check:licenses`.
import licenseManifest from "../../resources/licenses/manifest.json";
import notices from "../../resources/licenses/THIRD-PARTY-NOTICES.txt?raw";
import { NOT_MEASURED } from "../shared/placeholder";

export function TrustScreen({
  state,
  actions,
  dispatch,
  onPurge,
}: {
  state: State;
  actions: ActionsApi;
  dispatch: Dispatch<Action>;
  onPurge: () => void;
}) {
  const t = useT();
  const info = state.info;
  const [note, setNote] = useState("");
  /** The bundle this session actually created, or `null`. Never a placeholder. */
  const [bundle, setBundle] = useState<SupportBundle | null>(null);

  if (!info) {
    return <p className="empty">{t("misc.loading")}</p>;
  }

  return (
    <section className="screen">
      <header className="screen-head">
        <div>
          <h2>{t("trust.title")}</h2>
          <p className="muted">{t("trust.subtitle")}</p>
        </div>
        <span className={`pill ${info.simulator ? "pill-warn" : ""}`}>
          {info.simulator ? t("mode.simulation") : t("misc.offline")}
        </span>
      </header>

      <div className="two-col">
        <article className="panel">
          <h3>{t("help.about")}</h3>
          <dl className="facts">
            <div><dt>{t("trust.version")}</dt><dd>{info.version}</dd></div>
            <div><dt>{t("trust.build")}</dt><dd className="mono">{info.buildCommit}</dd></div>
            <div><dt>{t("trust.signature")}</dt><dd>{t(`trust.signature.${info.signature.status}`)}</dd></div>
            {info.signature.publisher ? (
              <div>
                <dt>{t("trust.publisher")}</dt>
                <dd>{info.signature.publisher}</dd>
              </div>
            ) : null}
            <div>
              <dt>{t("trust.os")}</dt>
              <dd>
                {/* DEF-127: `osBuild`/`osDisplayVersion` are `null` when the
                    registry read failed. The old markup printed `" (0)"`, a
                    version invented from a failed read. */}
                {info.osBuild === null && info.osDisplayVersion === null
                  ? t("trust.notMeasured")
                  : t("trust.os.value", {
                      version: info.osDisplayVersion ?? t("trust.notMeasured"),
                      build: info.osBuild === null ? NOT_MEASURED : String(info.osBuild),
                    })}
              </dd>
            </div>
            <div><dt>{t("trust.arch")}</dt><dd>{info.arch}</dd></div>
            <div>
              <dt>{t("trust.webview")}</dt>
              {/* DEF-128: the catalogue owns the word, not the core. */}
              <dd>{info.webviewVersion ?? t("trust.notMeasured")}</dd>
            </div>
            <div><dt>{t("trust.privilege")}</dt><dd>{info.isElevated ? t("mode.admin") : t("mode.standard")}</dd></div>
            <div><dt>{t("trust.store")}</dt><dd className="mono small">{info.storePath}</dd></div>
            <div><dt>{t("trust.storeMode")}</dt><dd>{t(info.storeMode === "machine" ? "trust.storeMode.machine" : "trust.storeMode.user")}</dd></div>
            <div><dt>{t("trust.session")}</dt><dd>{t("trust.session.uptime", { time: t.formatDuration(state.sessionUptimeMs) })}</dd></div>
            <div>
              <dt>{t("trust.boot")}</dt>
              <dd>
                {state.bootMs === null
                  ? t("trust.boot.unknown")
                  : t("trust.boot.value", { ms: String(state.bootMs) })}
              </dd>
            </div>
          </dl>
        </article>

        <article className="panel">
          <h3>{t("trust.privacy")}</h3>
          <p>{t("trust.privacy.body")}</p>
          <h3>{t("trust.telemetry")}</h3>
          <p>{t(state.telemetryEnabled ? "trust.telemetry.on" : "trust.telemetry.off")}</p>
          <h3>{t("trust.permissions")}</h3>
          <p>{t("trust.permissions.body")}</p>
        </article>
      </div>

      <article className="panel">
        <h3>{t("trust.bundle")}</h3>
        <p className="muted">{t("trust.bundle.subtitle")}</p>
        <label className="field">
          <span>{t("trust.bundle.note")}</span>
          <textarea
            rows={3}
            value={note}
            placeholder={t("trust.bundle.note.placeholder")}
            onChange={(event) => setNote(event.target.value)}
          />
        </label>
        <div className="card-actions">
          <button
            className="btn btn-primary"
            type="button"
            onClick={async () => {
              const bundle = await actions.createBundle(note);
              if (bundle) {
                setBundle(bundle);
                setNote("");
              }
            }}
          >
            {t("trust.bundle.action")}
          </button>
          <button className="btn btn-quiet" type="button" onClick={() => void actions.refresh()}>
            {t("misc.retry")}
          </button>
        </div>

        {/*
         * The screen either shows the bundle it actually created (path, size,
         * included files, redaction counts) or nothing. It never claims a
         * bundle exists because a button was pressed.
         */}
        {bundle ? (
          <div className="bundle-result" role="status">
            <p>
              {t("trust.bundle.done", {
                bytes: t.formatBytes(bundle.bytes),
                path: bundle.path,
              })}
            </p>
            <h4>{t("trust.bundle.contents")}</h4>
            <ul className="mono small">
              {bundle.includedFiles.map((file) => (
                <li key={file}>{file}</li>
              ))}
            </ul>
            <h4>{t("trust.bundle.redaction")}</h4>
            <p className="muted small">
              {t("trust.bundle.redaction.value", {
                masked: bundle.redactionReport.maskedValues,
                paths: bundle.redactionReport.scrubbedPaths,
              })}
            </p>
          </div>
        ) : null}
      </article>

      <article className="panel">
        <h3>{t("trust.purge")}</h3>
        <p className="muted">{t("trust.purge.subtitle")}</p>
        <button className="btn btn-danger" type="button" onClick={onPurge}>
          {t("trust.purge.action")}
        </button>
        <button
          className="btn btn-quiet"
          type="button"
          onClick={() => dispatch({ type: "screen/set", screen: "snapshots" })}
        >
          {t("status.snapshots")}
        </button>
      </article>

      <article className="panel">
        <h3>{t("trust.licenses")}</h3>
        <p className="muted">
          {t("trust.licenses.body", { count: licenseManifest.counts.components })}
        </p>
        <details className="licenses">
          <summary>{t("trust.licenses.show")}</summary>
          <pre className="licenses-text">{notices}</pre>
        </details>
        <p className="muted small">{t("trust.licenses.source")}</p>
      </article>
    </section>
  );
}
